command:
// ==========================================
// LUNAS WIRKUNG: SCHNURREN DER MUTTER (NURTI)
//
// - bis zu QS gültige Ziele (Lebewesen mit fehlenden LeP)
// - alle weiteren / ungültigen Targets = Misserfolg, Gabe geht dennoch durch
// - DialogV2 zur Auswahl der 10-Minuten-Intervalle (max. QS)
// - Heilung: +1 LeP pro Intervall (bis maxLeP)
// - Anzeige auf beiden Karten nur (+X LeP), keine genauen LeP-Stände
// - gespeicherte Ziele | GM-Button | gemeinsame Karte über GabenUI
// ==========================================

(async function () {
const macroUuid = this?.uuid || game.macros.getName("Schnurren der Mutter")?.uuid || null;

// +++ 1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++

const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
const frameworkFehlt =
    !globalThis.DSK?.QS?.Ermitteln || !globalThis.DSK?.Token?.Finde ||
    !globalThis.DSK?.Wesen?.IstLebendig ||
    !globalThis.DSK?.GMAnfrage?.Speichern || !globalThis.DSK?.GMAnfrage?.Finden ||
    !globalThis.DSK?.GMAnfrage?.Lesen || !globalThis.DSK?.GMAnfrage?.Loeschen ||
    !globalThis.DSK?.GabenUI?.GMMakroButton ||
    !globalThis.DSK?.GabenUI?.AnfrageKarteErstellen ||
    !globalThis.DSK?.GabenUI?.AnfrageKarteAktualisieren;

if (frameworkFehlt) {
    const fwMacro = await fromUuid(frameworkUuid);
    if (!fwMacro?.execute) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!");
    await fwMacro.execute();
    await new Promise(resolve => setTimeout(resolve, 150));
}

const DSK_FW = globalThis.DSK;
if (
    !DSK_FW?.QS?.Ermitteln || !DSK_FW?.Token?.Finde ||
    !DSK_FW?.Wesen?.IstLebendig ||
    !DSK_FW?.GMAnfrage?.Speichern || !DSK_FW?.GMAnfrage?.Finden ||
    !DSK_FW?.GMAnfrage?.Lesen || !DSK_FW?.GMAnfrage?.Loeschen ||
    !DSK_FW?.GabenUI?.GMMakroButton ||
    !DSK_FW?.GabenUI?.AnfrageKarteErstellen ||
    !DSK_FW?.GabenUI?.AnfrageKarteAktualisieren
) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework 01.02 wurde nicht vollständig geladen!");

// +++ 2 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++++

const gabenName = "Schnurren der Mutter", vollerName = "Schnurren der Mutter (Nurti)", ahne = "Nurti";
const flagKey = "pendingSchnurrenDerMutterNurti";
const iconBild = DSK_FW.Symbol(ahne);

// +++ 3 - HILFSFUNKTIONEN +++++++++++++++++++++++++++++++++

const raeumeQSAuf = async actor => {
    if (actor?.getFlag("world", "letzteGabenQS") !== undefined) await actor.unsetFlag("world", "letzteGabenQS");
    if (actor?.getFlag("world", "letzteGabenMessageId") !== undefined) await actor.unsetFlag("world", "letzteGabenMessageId");
};

const ladeActor = async uuid => {
    if (!uuid) return null;
    try {
        const doc = await fromUuid(uuid);
        return doc?.documentName === "Token" ? doc.actor : doc || null;
    } catch (error) {
        console.warn("Schnurren der Mutter: Actor konnte nicht geladen werden.", { uuid, error });
        return null;
    }
};

const istGueltigesLebewesen = actor => {
    if (!actor) return false;
    return DSK_FW.Wesen.IstLebendig(actor, { zusaetzlichAusgeschlossen: ["elementar"] });
};

const beschreibungFuer = (casterName, intervalle, qs) =>
    `<b>${casterName}</b> hält Körperkontakt und beginnt tief und beruhigend zu schnurren.` +
    `<br><br>Das vibrierende Schnurren durchdringt den Körper des Ziels, schließt langsam die Wunden und kann im Notfall sogar vor dem Tod bewahren.` +
    `<br><br><b>Heilung:</b> +${intervalle} LeP (${intervalle} × 10 Minuten)` +
    `<br><b>Maximale Ziele:</b> ${qs} (QS) | <b>Zielkategorie:</b> Lebewesen`;

// +++ 4 - HEILUNG ANWENDEN ++++++++++++++++++++++++++++++++

const heileZiel = async ({ targetActor, targetName, intervalle }) => {
    if (!targetActor || !istGueltigesLebewesen(targetActor)) {
        return { ok: false, name: `${targetName} (Kein Lebewesen)` };
    }

    const maxLeP = Number(targetActor.system?.stats?.LeP?.max) || 0;
    const currentLeP = Number(targetActor.system?.stats?.LeP?.value) || 0;

    if (currentLeP >= maxLeP) {
        return { ok: false, name: `${targetName} (Bereits volle LeP)` };
    }

    let healAmount = Math.max(1, Math.floor(Number(intervalle) || 1));
    let neueLeP = currentLeP + healAmount;
    if (neueLeP > maxLeP) {
        healAmount = maxLeP - currentLeP;
        neueLeP = maxLeP;
    }

    await targetActor.update({ "system.stats.LeP.value": neueLeP });

    return {
        ok: true,
        name: `${targetName} (+${healAmount} LeP)`,
        healAmount
    };
};

// +++ 5 - GM-ANFRAGE VERARBEITEN ++++++++++++++++++++++++++

const verarbeiteAnfrage = async (casterActor, daten) => {
    if (!casterActor || !daten || !game.user.isGM) return false;

    if (daten.casterUuid && daten.casterUuid !== casterActor.uuid) {
        ui.notifications.warn("Luna sagt 🌙: Die gespeicherte Anfrage passt nicht zum Wirkenden.");
        return false;
    }

    if (daten.sceneId && daten.sceneId !== canvas.scene?.id) {
        ui.notifications.warn(`Luna sagt 🌙: Die Anfrage von „${casterActor.name}“ gehört zu einer anderen Szene.`);
        return false;
    }

    const qs = Math.max(1, Math.floor(Number(daten.qs) || 1));
    const intervalle = Math.max(1, Math.min(qs, Math.floor(Number(daten.intervalle) || 1)));
    const minutenGesamt = intervalle * 10;
    const casterName = daten.casterName || DSK_FW.ResolveTokenName(casterActor);
    const erfolge = [], misserfolge = foundry.utils.deepClone(daten.misserfolge || []);

    for (const ziel of daten.ziele || []) {
        const targetActor = await ladeActor(ziel.actorUuid);
        const targetName = ziel.name || DSK_FW.ResolveTokenName(targetActor) || "Unbekanntes Ziel";

        if (!targetActor) {
            misserfolge.push({ name: `${targetName} (Nicht gefunden)` });
            continue;
        }

        try {
            const resultat = await heileZiel({ targetActor, targetName, intervalle });
            if (resultat.ok) {
                erfolge.push({ name: resultat.name, rolle: "Erfolgreich geheilt" });
            } else {
                misserfolge.push({ name: resultat.name });
            }
        } catch (error) {
            console.error("Schnurren der Mutter: Heilung fehlgeschlagen.", { ziel, error });
            misserfolge.push({ name: `${targetName} (Heilung fehlgeschlagen)` });
        }
    }

    const erfolgreich = erfolge.length > 0;

    await DSK_FW.GabenUI.AnfrageKarteAktualisieren({
        messageId: daten.messageId,
        gabenName: vollerName,
        ahne,
        beschreibung: daten.beschreibung || beschreibungFuer(casterName, intervalle, qs),
        wirkender: casterName,
        ziele: erfolge,
        misserfolge,
        dauerText: `${minutenGesamt} Minuten (${intervalle} × 10 Min)`,
        erfolgreich
    });

    if (erfolgreich) {
        ui.notifications.info(`Luna sagt 🌙: Schnurren der Mutter hat ${erfolge.length} Ziel(e) geheilt.`);
    } else {
        ui.notifications.error("Luna sagt 🌙: Schnurren der Mutter konnte auf kein Ziel angewendet werden!");
    }

    return true;
};

// +++ 6 - GM-MODUS ++++++++++++++++++++++++++++++++++++++++

if (game.user.isGM) {
    const anfragen = DSK_FW.GMAnfrage.Finden(flagKey);

    if (anfragen.length) {
        for (const anfrageActor of anfragen) {
            const daten = DSK_FW.GMAnfrage.Lesen(anfrageActor, flagKey);
            if (!daten) continue;

            if (await verarbeiteAnfrage(anfrageActor, daten)) {
                await DSK_FW.GMAnfrage.Loeschen(anfrageActor, flagKey);
            }
        }

        return;
    }
}

// +++ 7 - WIRKENDER UND QS ++++++++++++++++++++++++++++++++

let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character || null;

if (!casterActor) {
    casterActor =
        canvas.tokens.placeables.map(token => token.actor)
            .find(actor => actor?.getFlag("world", "letzteGabenQS") !== undefined) ||
        game.actors.find(actor => actor.getFlag("world", "letzteGabenQS") !== undefined) ||
        null;
}

if (!casterActor) return ui.notifications.warn("Luna sagt 🌙: Bitte wähle zuerst deinen Token aus!");
if (!game.user.isGM && !casterActor.isOwner) return ui.notifications.warn("Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!");

const casterToken = DSK_FW.Token.Finde(casterActor);
if (!casterToken) return ui.notifications.warn("Luna sagt 🌙: Der Wirkende braucht einen Token auf der aktuellen Szene!");

const casterName = DSK_FW.ResolveTokenName(casterActor);
const qs = DSK_FW.QS.Ermitteln({
    actor: casterActor,
    gabenName,
    suchbegriffe: ["Schnurren der Mutter Probe", "Schnurren der Mutter", "Schnurren"],
    testDataObj: typeof testData !== "undefined" ? testData : null,
    fallback: 0,
    protokollieren: true
});

if (qs <= 0) {
    await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName,
        ahne,
        beschreibung: "Das heilende Schnurren konnte nicht angestimmt werden.",
        wirkender: casterName,
        ziele: [],
        misserfolge: [{ name: casterName }],
        dauerText: "Keine Wirkung",
        gmBereich: false,
        angewendet: true,
        erfolgreich: false,
        anfragenderUserId: game.user.id
    });

    await raeumeQSAuf(casterActor);
    return;
}

// +++ 8 - TARGETS VORPRÜFEN +++++++++++++++++++++++++++++++

const targets = Array.from(game.user.targets || []);
if (!targets.length) {
    return ui.notifications.warn("Luna sagt 🌙: Bitte wähle zuerst jemanden per Target aus, den du beschnurren möchtest!");
}

// +++ 9 - DIALOGV2 FÜR DIE SCHNURR-INTERVALLE +++++++++++++

const maxIntervalle = qs;
const dialogContent = `
    <form>
        <div style="font-family: 'Signika', sans-serif;">
            ${DSK_FW.UI.Header(vollerName, iconBild)}
            <div class="dskbox2" style="margin-top: 10px; color: #000; text-align: left;">
                <p style="margin-bottom: 10px;"><b>Wie lange möchtest du schnurren?</b></p>
                <p style="font-size: 0.9em; margin-bottom: 10px; color: #555;">(Jedes 10-Minuten-Intervall heilt 1 LeP. Deine QS erlaubt maximal <b>${maxIntervalle}</b> Intervalle und bis zu <b>${qs}</b> Ziel(e).)</p>
                <div style="display: flex; align-items: center; justify-content: flex-start; gap: 10px; margin-bottom: 5px;">
                    <label style="font-weight: bold;">10-Minuten-Intervalle:</label>
                    <input type="number" name="putzIntervalle" value="${maxIntervalle}" min="1" max="${maxIntervalle}" style="width: 60px; text-align: center; border: 1px solid #76301b; border-radius: 3px;">
                </div>
            </div>
        </div>
    </form>
`;

const dialogResult = await foundry.applications.api.DialogV2.wait({
    window: { title: `Schnurren (Max: ${maxIntervalle * 10} Min)` },
    position: { width: 420 },
    content: dialogContent,
    rejectClose: false,
    buttons: [
        {
            action: "confirm",
            label: "Schnurren & Heilen",
            icon: "fas fa-heart",
            default: true,
            callback: (event) => {
                const form = event.target.closest("form");
                return form ? Number(new FormData(form).get("putzIntervalle")) || 0 : 0;
            }
        },
        {
            action: "cancel",
            label: "Abbrechen",
            icon: "fas fa-times",
            callback: () => false
        }
    ]
});

if (dialogResult === false || dialogResult === undefined) return;

let intervalle = Math.floor(Number(dialogResult) || 0);
if (intervalle <= 0) {
    return ui.notifications.warn("Luna sagt 🌙: Du musst schon mindestens 10 Minuten schnurren!");
}
if (intervalle > maxIntervalle) intervalle = maxIntervalle;

const minutenGesamt = intervalle * 10;
const dauerText = `${minutenGesamt} Minuten (${intervalle} × 10 Min)`;
const beschreibung = beschreibungFuer(casterName, intervalle, qs);

// +++ 10 - ZIELE PRÜFEN & NACH QS BEGRENZEN +++++++++++++++

const gueltigeZiele = [];
const misserfolge = [];

for (const targetToken of targets) {
    const targetActor = targetToken?.actor;
    const targetName = targetToken?.name || targetActor?.name || "Unbekanntes Ziel";

    if (!targetActor || !istGueltigesLebewesen(targetActor)) {
        misserfolge.push({ name: `${targetName} (Kein Lebewesen)` });
        continue;
    }

    const maxLeP = Number(targetActor.system?.stats?.LeP?.max) || 0;
    const currentLeP = Number(targetActor.system?.stats?.LeP?.value) || 0;

    if (currentLeP >= maxLeP) {
        misserfolge.push({ name: `${targetName} (Bereits volle LeP)` });
        continue;
    }

    if (gueltigeZiele.length >= qs) {
        misserfolge.push({ name: `${targetName} (QS-Limit von ${qs} überschritten)` });
        continue;
    }

    const vorschauHeilung = Math.min(intervalle, maxLeP - currentLeP);

    gueltigeZiele.push({
        actorUuid: targetActor.uuid,
        tokenId: targetToken.id,
        tokenUuid: targetToken.document?.uuid || targetToken.uuid || null,
        name: targetName,
        vorschauName: `${targetName} (+${vorschauHeilung} LeP)`
    });
}

if (!gueltigeZiele.length) {
    await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName,
        ahne,
        beschreibung,
        wirkender: casterName,
        ziele: [],
        misserfolge,
        dauerText: "Keine Wirkung",
        gmBereich: false,
        angewendet: true,
        erfolgreich: false,
        anfragenderUserId: game.user.id
    });

    await raeumeQSAuf(casterActor);
    return;
}

// +++ 11 - GEMEINSAME KARTE + GM-ANFRAGE ++++++++++++++++++

const gmLink = DSK_FW.GabenUI.GMMakroButton(
    macroUuid,
    "Heilung anwenden",
    "Das Makro muss durch die Spielleitung ausgeführt werden."
);

const nachricht = await DSK_FW.GabenUI.AnfrageKarteErstellen({
    gabenName: vollerName,
    ahne,
    beschreibung,
    wirkender: casterName,
    ziele: gueltigeZiele.map(z => ({ name: z.vorschauName, rolle: "Erfolgreich geheilt" })),
    misserfolge,
    dauerText,
    gmLink,
    gmBereich: !game.user.isGM,
    anfragenderUserId: game.user.id
});

if (!nachricht) {
    await raeumeQSAuf(casterActor);
    return ui.notifications.error("Luna sagt 🌙: Die Wirkungskarte konnte nicht erstellt werden!");
}

const anfrageDaten = {
    casterUuid: casterActor.uuid,
    casterName,
    casterTokenId: casterToken.id,
    casterTokenUuid: casterToken.document?.uuid || casterToken.uuid || null,
    qs,
    intervalle,
    ziele: gueltigeZiele,
    misserfolge,
    beschreibung,
    sceneId: canvas.scene?.id || null,
    requestedByUserId: game.user.id,
    messageId: nachricht.id,
    macroUuid,
    erstellt: Date.now()
};

if (game.user.isGM) {
    await verarbeiteAnfrage(casterActor, anfrageDaten);
    await raeumeQSAuf(casterActor);
    return;
}

await DSK_FW.GMAnfrage.Speichern(casterActor, flagKey, anfrageDaten);
await raeumeQSAuf(casterActor);
ui.notifications.info("Luna sagt 🌙: Schnurren der Mutter wurde bei der Spielleitung zur Heilung beantragt.");

}).call(this);
